"""Private vault handles -> run-scoped Browser Use secrets, through Composio.

Models supply goals and local session names, never provider IDs or credential
values. Provider IDs live in the protected gateway directory. Browser state is
keyed by the authenticated conversation context, never a model-supplied owner.
"""
import hashlib
import json
from pathlib import Path
import re
from urllib.parse import urlsplit

from vault.store import AccessError
from .client import ComposioBrowserClient, ComposioBrowserToolClient

TERMINAL = {'completed', 'failed', 'cancelled'}
from vault.login import LOGIN_FIELDS, OTP_FIELDS, PHONE_FIELDS


def configured(vault_service):
    path = vault_service.policy.home / '.clanker-cloud' / 'config.json'
    if not path.exists():
        return None
    settings = json.loads(path.read_text())
    if not settings.get('enabled'):
        return None
    if settings.get('provider') == 'browser_tool':
        fields = {'enabled', 'provider', 'organization_id', 'project_id', 'connection_user_id', 'tool_version'}
        if set(settings) != fields or not all(isinstance(settings[k], str) and settings[k]
                for k in fields - {'enabled'}):
            raise AccessError('The consumer browser connection is incomplete.', 503)
        from agent.secret_scope import build_profile_secret_scope
        key = build_profile_secret_scope(vault_service.policy.home).get('CLANKER_COMPOSIO_USER_API_KEY')
        if not key:
            raise AccessError('Authorize the Composio consumer account before enabling Browser Tool.', 503)
        from .browser_tool import BrowserTool
        return BrowserTool(vault_service, settings, ComposioBrowserToolClient(settings, key))
    if set(settings) != {'enabled', 'connected_account_id', 'connection_user_id', 'tool_version', 'max_cost_usd'}:
        raise AccessError('The cloud browser configuration has unsupported fields.', 503)
    if not all(isinstance(settings[k], str) and settings[k] for k in ('connected_account_id', 'connection_user_id', 'tool_version')):
        raise AccessError('The cloud browser connection is incomplete.', 503)
    if isinstance(settings['max_cost_usd'], bool) or not 0 < float(settings['max_cost_usd']) <= 100:
        raise AccessError('The cloud browser requires a positive per-run cost limit.', 503)
    from agent.secret_scope import build_profile_secret_scope
    key = build_profile_secret_scope(vault_service.policy.home).get('CLANKER_COMPOSIO_API_KEY')
    if not key:
        raise AccessError('Configure the Composio project key before enabling the cloud browser.', 503)
    return CloudBrowser(vault_service, settings, ComposioBrowserClient(settings, key))


class CloudBrowser:
    profile_retained_on_stop = True
    def __init__(self, vault_service, settings, client):
        self.vault = vault_service
        self.settings = settings
        self.client = client
        self.directory = vault_service.policy.home / '.clanker-cloud'

    def context_key(self, turn):
        self.vault.validate_member(turn.source.scope_id, turn.source.user_id)
        if not self.vault.policy.authorize_source(turn.source):
            raise AccessError('This browser context is not authorized.', 403)
        return hashlib.sha256(('v2:' + turn.source.scope_id + ':' + turn.source.user_id + ':' + str(turn.home.resolve())).encode()).hexdigest()

    def owned_state(self, turn, path):
        owner = {'team': turn.source.scope_id, 'requester': turn.source.user_id}
        state = json.loads(path.read_text()) if path.exists() else {'owner': owner, 'sessions': {}, 'threads': {}}
        if state.get('owner') != owner:
            raise AccessError('The browser state has no verified requester ownership.', 403)
        return state

    def claim_session(self, turn, session_id):
        owner = (turn.source.scope_id, turn.source.user_id, self.context_key(turn))
        provider = type(self).__name__
        with self.vault.store.connection() as db:
            db.execute('BEGIN IMMEDIATE')
            row = db.execute('SELECT team,requester,context FROM browser_session_owners WHERE provider=? AND session_id=?',
                             (provider, session_id)).fetchone()
            if row and tuple(row) != owner:
                raise AccessError('The provider returned a browser assigned to another requester. This task is quarantined.', 403)
            db.execute('INSERT OR IGNORE INTO browser_session_owners VALUES (?,?,?,?,?)',
                       (provider, session_id, *owner))

    def check_access(self, turn, entry):
        if entry.get('cleanup_pending'):
            raise AccessError('Browser cookie cleanup has not been verified. This account context remains blocked.', 403)
        self.vault.delegations.check_execution(turn)
        if entry.get('access_handle'):
            self.vault.delegations.resolve(turn, entry['access_handle'])

    def bind_access(self, turn, access):
        self.vault.delegations.resolve(turn, access.handle)
        self.vault.delegations.check_execution(turn)
        path, state = self.state(turn)
        _, entry = self.selected(turn, state)
        if entry.get('access_handle') not in (None, access.handle):
            raise AccessError('This browser is bound to another credential. Stop it before opening a different account.', 403)
        entry['access_handle'] = access.handle
        self.save(path, state)
        self.vault.delegations.record_browser_use(turn, access)

    def state(self, turn):
        key = self.context_key(turn)
        path = self.directory / 'contexts' / (key + '.json')
        return path, self.owned_state(turn, path)

    def save(self, path, state):
        from seatbelt.install import write
        write(path, json.dumps(state, indent=2) + '\n')

    def thread(self, turn):
        return turn.source.chat_id + ':' + str(turn.source.thread_id or '')

    def selected(self, turn, state, session=None):
        name = session or state['threads'].get(self.thread(turn))
        if not name or name not in state['sessions']:
            raise AccessError('Start or select this thread\'s cloud browser before using saved access.', 409)
        return name, state['sessions'][name]

    def execute(self, name, args):
        return self.client.execute('BROWSER_USE_' + name, args)

    def safe_result(self, turn, data):
        from agent.vault_store import VaultStore, scrub_secret_from_text
        text = str(data.get('result') or '')
        # Scrub every saved secret in this private context, including credentials
        # supplied on an earlier run. Never return raw provider responses.
        store = VaultStore(self.vault.private_home(turn.source.scope_id,turn.source.user_id) / 'vault')
        for meta in store.list_items():
            text = scrub_secret_from_text(text, store.resolve_secret(meta.id))
        # Preserve output scrubbing for one-time codes across gateway restarts.
        # Only encrypted values are persisted in the protected context record.
        _, state = self.state(turn)
        cipher = self.vault.store.code_crypto()
        for entry in state['sessions'].values():
            for encrypted in entry.get('redactions', []):
                text = scrub_secret_from_text(text, {'value': cipher.decrypt(encrypted.encode()).decode()})
        from agent.redact import redact_sensitive_text, redact_registered_vault_values
        text = redact_registered_vault_values(redact_sensitive_text(text,force=True))
        return {'status': data.get('status'), 'result': text,
                'success': data.get('status') == 'completed',
                'result_verified': False}

    def status(self, turn, session=None):
        with self.vault.lock_for(turn.home):
            path, state = self.state(turn)
            name, entry = self.selected(turn, state, session)
            self.check_access(turn, entry)
            if entry.get('dispatch_unknown'):
                raise AccessError('A previous dispatch was not acknowledged. The operator must reconcile it before another run.', 409)
            if not entry.get('run_id'):
                return {'status': 'idle', 'session': name}
            data = self.execute('GET_RUN_STATUS', {'run_id': entry['run_id']})
            entry['status'] = data['status']
            self.save(path, state)
            if data['status'] in TERMINAL:
                data = self.execute('GET_RUN', {'run_id': entry['run_id']})
            return {'session': name, **self.safe_result(turn, data)}

    def start(self, turn, task, session='web', *, bindings=None):
        if not isinstance(task, str) or not task.strip() or len(task) > 20000:
            raise AccessError('Supply a browser task of at most 20,000 characters.')
        if not isinstance(session, str) or not re.fullmatch(r'[a-z0-9][a-z0-9_-]{0,39}', session):
            raise AccessError('Use a short lowercase browser session name.')
        with self.vault.lock_for(turn.home):
            path, state = self.state(turn)
            entry = state['sessions'].setdefault(session, {})
            self.check_access(turn, entry)
            if entry.get('dispatch_unknown'):
                raise AccessError('A previous dispatch was not acknowledged. Ask the operator to reconcile it.', 409)
            if entry.get('run_id'):
                current = self.execute('GET_RUN_STATUS', {'run_id': entry['run_id']})
                if current['status'] not in TERMINAL:
                    return {'status': current['status'], 'session': session,
                            'next': 'Use clanker_browser_status; the existing run is still active.'}
            state['threads'][self.thread(turn)] = session
            entry['dispatch_unknown'] = True
            self.save(path, state)
            if not entry.get('profile_id'):
                profile = self.execute('CREATE_PROFILE', {'name': 'clanker-' + session,
                    'user_id': self.context_key(turn)})
                entry['profile_id'] = profile['id']
                self.save(path, state)
            args = {'task': task, 'agentmail': False,
                    'browser_settings': {'profileId': entry['profile_id'], 'record': False},
                    'max_cost_usd': self.settings['max_cost_usd']}
            if entry.get('session_id'):
                args['session_id'] = entry['session_id']
            if bindings:
                # Only trusted fill/code handlers can construct this argument.
                self.vault.assert_private(turn)
                args['secret_bindings'] = bindings
                cipher = self.vault.store.code_crypto()
                entry['redactions'] = (entry.get('redactions', []) + [
                    cipher.encrypt(item['source']['value'].encode()).decode() for item in bindings
                ])[-64:]
                self.save(path,state)
            run = self.execute('START_RUN', args)
            self.claim_session(turn, run['sessionId'])
            entry.update(run_id=run['id'], session_id=run['sessionId'],
                         status=run['status'], dispatch_unknown=False)
            entry.pop('browser_id', None)
            self.save(path, state)
            return {'status': run['status'], 'session': session,
                    'next': 'Use clanker_browser_status until this run ends. Verify the reported website result before claiming success.'}

    def browser(self, turn, entry, *, require_active=True):
        cursor = None
        latest = None
        # Read all ordered events, including browser.reattached on follow-ups.
        for _ in range(100):
            args = {'run_id': entry['run_id'], 'limit': 100, 'include_output': False}
            if cursor:
                args['after'] = cursor
            data = self.execute('LIST_RUN_EVENTS', args)
            for event in data.get('events', []):
                if event.get('type') in ('browser.ready', 'browser.reattached'):
                    latest = event.get('data', {}).get('browser_session_id')
            cursor = data.get('next_cursor')
            if not cursor and data.get('hasMore'):
                cursor = str(data.get('nextAfter'))
            if not cursor:
                break
        else:
            raise AccessError('Cloud browser discovery exceeded its event limit.', 502)
        if latest:
            entry['browser_id'] = latest
        if not entry.get('browser_id'):
            if not require_active:
                return None
            raise AccessError('The cloud browser is not ready or has already stopped.', 409)
        browser = self.execute('GET_BROWSER_SESSION', {'session_id': entry['browser_id']})
        if browser.get('agentSessionId') != entry['session_id'] or (require_active and browser.get('status') != 'active'):
            raise AccessError('The browser does not belong to this active session.', 403)
        return browser

    def login_origin(self, turn, expected='', *, otp=False, phone=False):
        self.vault.assert_private(turn)
        with self.vault.lock_for(turn.home):
            path, state = self.state(turn)
            _, entry = self.selected(turn, state)
            if not entry.get('run_id') or self.execute('GET_RUN_STATUS', {'run_id': entry['run_id']})['status'] not in TERMINAL:
                raise AccessError('Wait for the browser run to stop before requesting or filling credentials.', 409)
            browser = self.browser(turn, entry)
            self.save(path, state)
            cdp = str(browser.get('cdpUrl') or '')
            url = urlsplit(cdp)
            if url.scheme != 'wss' or not url.hostname or not (url.hostname == 'browser-use.com' or url.hostname.endswith('.browser-use.com')) or url.username or url.port not in (None, 443):
                raise AccessError('The cloud browser returned an unsupported control endpoint.', 502)
            from tools.browser_supervisor import CDPSupervisor
            supervisor = CDPSupervisor('clanker-cloud-' + self.context_key(turn)[:12], cdp)
            try:
                supervisor.start()
                found = supervisor.focus_page(expected, accept=OTP_FIELDS if otp else PHONE_FIELDS if phone else LOGIN_FIELDS)
                observed = supervisor.evaluate_runtime('location.origin') if found.get('ok') else {}
                origin = observed.get('result') if observed.get('ok') else None
            except Exception:
                raise AccessError('Could not inspect the cloud login page securely.', 502) from None
            finally:
                supervisor.stop()
            if not origin or urlsplit(origin).scheme != 'https' or (expected and origin != expected):
                raise AccessError('The live login page does not match the saved account origin.', 403)
            return origin

    def fill(self, turn, meta, *, code=None, access=None):
        self.vault.assert_private(turn)
        with self.vault.lock_for(turn.home):
            self.login_origin(turn, meta.origin, otp=code is not None, phone=meta.login_method=='sms' and code is None)
            access = access or self.vault.delegations.resolve(turn, meta.id)
            self.bind_access(turn, access)
            from agent.vault_store import VaultStore
            sms = meta.login_method=='sms'
            value = code if code is not None else access.secret()['phone_number' if sms else 'password']
            from agent.redact import register_vault_redaction_value
            register_vault_redaction_value(value)
            alias = 'verification_code' if code is not None else 'phone_number' if sms else 'account_password'
            _, state = self.state(turn)
            name, _ = self.selected(turn, state)
            task = ('On the current login page, enter ' + alias + ' in its ' +
                    ('verification-code' if code is not None else 'phone-number' if sms else 'password') +
                    ' field and stop before submitting. Stay on ' + meta.origin +
                    '. Do not read, reveal, or copy the entered value. '
                    + ('For a phone field with a separate visible calling code matching the saved number prefix, use its national digits; otherwise preserve the full number. Never guess or truncate digits to fit. ' if sms and code is None else '')
                    + ('' if code is not None or sms else 'If needed, enter the account identifier ' + json.dumps(meta.identifier) + ' first.'))
            return self.start(turn, task, name, bindings=[{'alias': alias,
                'source': {'type': 'inline', 'value': value},
                'allowedDomains': [urlsplit(meta.origin).hostname]}])

    def stop(self, turn, session=None, *, purge=False):
        with self.vault.lock_for(turn.home):
            path, state = self.state(turn)
            if purge:
                names = list(state['sessions'])
            elif not session and not turn.source.thread_id:
                names = list({name for thread,name in state['threads'].items()
                              if thread.startswith(turn.source.chat_id+':')})
            else:
                names = [session or state['threads'].get(self.thread(turn))]
            pending = False
            for name in names:
                if name not in state['sessions']:
                    continue
                entry = state['sessions'][name]
                errors = []
                if entry.get('dispatch_unknown'):
                    errors.append(AccessError('An unacknowledged run must be reconciled before cloud access can be cleared.', 409))
                browser = None
                if entry.get('run_id'):
                    status = None
                    try:
                        status = self.execute('GET_RUN_STATUS', {'run_id': entry['run_id']})['status']
                    except Exception as error:
                        errors.append(error)
                    if status not in TERMINAL:
                        try:
                            self.execute('CANCEL_RUN', {'run_id': entry['run_id']})
                        except Exception as error:
                            errors.append(error)
                    try:
                        # Discover the browser even if no credential inspection ran.
                        browser = self.browser(turn, entry,require_active=False)
                    except Exception as error:
                        errors.append(error)
                if browser and browser.get('status')=='active':
                    try:
                        self.execute('STOP_BROWSER_SESSION', {'session_id': entry['browser_id']})
                    except Exception as error:
                        errors.append(error)
                if purge and entry.get('profile_id'):
                    try:
                        self.execute('DELETE_PROFILE', {'profile_id': entry['profile_id']})
                    except Exception as error:
                        errors.append(error)
                if errors:
                    pending = True
                    entry['cleanup_pending'] = True
                    self.save(path, state)
                    continue
                entry.pop('run_id', None)
                entry.pop('session_id', None)
                entry.pop('browser_id', None)
                if purge:
                    state['sessions'].pop(name)
                self.save(path, state)
            if pending:
                raise AccessError('Cloud browser cleanup is still pending. This context remains blocked until cleanup is verified.', 409)
"""Small browser-only model surface; secrets and provider IDs are backend-owned."""
import json

from vault.service import binding
from vault.store import AccessError

TOOLS = ['clanker_browser_run', 'clanker_browser_status', 'clanker_browser_stop']


def execute(name, args, **kwargs):
    try:
        allowed = {'clanker_browser_run': {'task', 'session'},
                   'clanker_browser_status': {'session'}, 'clanker_browser_stop': {'session'}}
        if name not in allowed or not isinstance(args, dict) or set(args) - allowed[name]:
            raise AccessError('Browser credentials and provider IDs are managed by the backend.', 403)
        turn = binding(kwargs.get('task_id'))
        cloud = turn.service.cloud_browser
        if cloud is None:
            raise AccessError('The Composio browser connection has not been configured.', 503)
        if name == 'clanker_browser_run':
            result = cloud.start(turn, **args)
        elif name == 'clanker_browser_status':
            result = cloud.status(turn, **args)
        else:
            cloud.stop(turn, **args)
            result = {'status': 'stopped', 'profile_retained': cloud.profile_retained_on_stop}
        return json.dumps(result)
    except AccessError as error:
        return json.dumps({'success': False, 'error': str(error), 'status': error.status})
    except Exception:
        return json.dumps({'success': False, 'error': 'The cloud browser operation failed. Do not repeat a task with side effects until its outcome is checked.'})


def register_tools(ctx):
    session = {'type': 'string', 'description': 'A consistent short lowercase name for this website, default web. Provider session IDs are managed by the backend.'}
    definitions = {
        'clanker_browser_run': ('Start or continue a hosted browser task. Stop at login when access is needed; use the private vault tools for credentials. This starts asynchronous work: poll status and verify the website outcome before claiming success. Use a consistent session name to reuse login cookies.',
            {'task': {'type': 'string'}, 'session': session}, ['task']),
        'clanker_browser_status': ('Read the current hosted browser task result. Call until completed, failed or cancelled. A completed result is the browser agent\'s report and requires verification for consequential actions.',
            {'session': session}, []),
        'clanker_browser_stop': ('Cancel this website\'s active task. Consumer Browser Tool cannot verify cookie deletion: profile_retained null means unknown, not logged out. Respect cleanup-pending errors. Do not stop while waiting for the owner\'s credential form.',
            {'session': session}, []),
    }
    for name, (description, properties, required) in definitions.items():
        schema = {'name': name, 'description': description, 'parameters': {'type': 'object',
            'properties': properties, 'required': required, 'additionalProperties': False}}
        ctx.register_tool(name, 'clanker_browser', schema,
            lambda args, _name=name, **kwargs: execute(_name, args, **kwargs), description=description, emoji='🌐')
"""Consumer Browser Tool with backend-owned sessions and scoped vault handoff.

Provider URL reports are not independent DOM inspection. Each hostname secret
contains only a password; codes use a run-scoped secret alias.
"""
import json
import re
from urllib.parse import urlsplit

from vault.store import AccessError
from .client import TaskInputRejected, TaskSessionExpired
from .service import CloudBrowser

TERMINAL = {'finished', 'stopped', 'failed'}
STATUS = {'started': 'running', 'finished': 'completed', 'stopped': 'cancelled', 'failed': 'failed'}


class BrowserTool(CloudBrowser):
    # STOP_TASK is not a cookie/profile deletion receipt.
    profile_retained_on_stop = None

    def state(self, turn):
        key = self.context_key(turn)
        path = self.directory / 'browser-tool-contexts' / (key + '.json')
        return path, self.owned_state(turn, path)

    def execute(self, name, args):
        return self.client.execute('BROWSER_TOOL_' + name, args)

    def watch(self, entry):
        data = self.execute('WATCH_TASK', {'taskId': entry['task_id']})
        if data.get('status') not in STATUS:
            raise AccessError('Browser Tool returned an unrecognized task status.', 502)
        return data

    def status(self, turn, session=None):
        with self.vault.lock_for(turn.home):
            path, state = self.state(turn)
            name, entry = self.selected(turn, state, session)
            self.check_access(turn, entry)
            if entry.get('dispatch_unknown'):
                raise AccessError('A dispatch was not acknowledged. The operator must reconcile it before another run.', 409)
            if not entry.get('task_id'):
                return {'status': 'idle', 'session': name}
            data = self.watch(entry)
            entry['status'] = data['status']
            self.save(path, state)
            result = self.safe_result(turn, {'status': STATUS[data['status']], 'result': data.get('output', '')})
            result['success'] = data['status'] == 'finished' and data.get('isSuccess') is True
            return {'session': name, **result}

    def start(self, turn, task, session='web', *, credentials=None, origin=None, secret_alias=None):
        if not isinstance(task, str) or not 10 <= len(task.strip()) <= 20000:
            raise AccessError('Supply a browser task of 10 to 20,000 characters.')
        if not isinstance(session, str) or not re.fullmatch(r'[a-z0-9][a-z0-9_-]{0,39}', session):
            raise AccessError('Use a short lowercase browser session name.')
        with self.vault.lock_for(turn.home):
            path, state = self.state(turn)
            entry = state['sessions'].setdefault(session, {})
            self.check_access(turn, entry)
            if entry.get('dispatch_unknown'):
                raise AccessError('A previous dispatch was not acknowledged. Ask the operator to reconcile it.', 409)
            if entry.get('task_id'):
                current = self.watch(entry)
                if current['status'] not in TERMINAL:
                    return {'status': STATUS[current['status']], 'session': session,
                            'next': 'Use clanker_browser_status; the existing task is still active.'}
                if entry.get('session_id'):
                    browser = self.execute('GET_SESSION', {'sessionId': entry['session_id']})
                    if browser.get('status') == 'stopped':
                        # Cloud browsers expire while the owner is away. A
                        # completed task receipt does not mean its browser is
                        # still reusable; start a fresh browser for this owner.
                        entry.pop('session_id', None)
                        entry.pop('task_id', None)
            args = {'task': task}
            if entry.get('session_id'):
                args['sessionId'] = entry['session_id']
            if credentials is not None:
                self.vault.assert_private(turn)
                parsed = urlsplit(origin or '')
                if (parsed.scheme != 'https' or not parsed.hostname or parsed.username or
                        parsed.port not in (None, 443) or '*' in origin):
                    raise AccessError('The saved credential requires an exact HTTPS origin.', 403)
                # The hosted action forwards secrets to Browser Use V2. Despite
                # Composio's URL-key example, V2 validates bare hostname keys.
                if secret_alias not in (None, 'verification_code', 'phone_number'):
                    raise AccessError('The credential alias is not supported.', 403)
                args['secrets'] = {secret_alias or parsed.hostname: credentials}
                # Keep the existing password/challenge page in a reused session.
                if not entry.get('session_id'):
                    args['startUrl'] = origin
                cipher = self.vault.store.code_crypto()
                entry['redactions'] = (entry.get('redactions', []) + [
                    cipher.encrypt(credentials.encode()).decode()
                ])[-64:]
            state['threads'][self.thread(turn)] = session
            entry['dispatch_unknown'] = True
            self.save(path, state)
            try:
                data = self.execute('CREATE_TASK', args)
            except TaskInputRejected as error:
                entry['dispatch_unknown'] = False
                entry['last_rejection'] = {'status_code': 422, 'task_created': False, 'log_id': error.log_id}
                self.save(path, state)
                raise
            except TaskSessionExpired as error:
                entry['dispatch_unknown'] = False
                entry['last_rejection'] = {'status_code': 400, 'task_created': False,
                                          'reason': 'stopped_browser', 'log_id': error.log_id}
                entry.pop('session_id', None)
                entry.pop('task_id', None)
                self.save(path, state)
                raise
            sid, tid = data.get('browser_session_id'), data.get('watch_task_id')
            if not all(isinstance(value, str) and value for value in (sid, tid)):
                raise AccessError('Browser Tool did not acknowledge the task and browser IDs. Ask the operator to reconcile it.', 502)
            self.claim_session(turn, sid)
            entry.update(session_id=sid, task_id=tid, status='started', dispatch_unknown=False)
            self.save(path, state)
            return {'status': 'running', 'session': session,
                    'next': 'Use clanker_browser_status until the task ends; verify the reported website result.'}

    def login_origin(self, turn, expected='', *, otp=False, phone=False):
        self.vault.assert_private(turn)
        with self.vault.lock_for(turn.home):
            _, state = self.state(turn)
            _, entry = self.selected(turn, state)
            if entry.get('dispatch_unknown') or not entry.get('task_id'):
                raise AccessError('Start the browser and stop at the login page first.', 409)
            data = self.watch(entry)
            if data['status'] not in TERMINAL:
                raise AccessError('Wait for the browser task to finish before requesting credentials.', 409)
            parsed = urlsplit(str(data.get('current_url') or ''))
            if parsed.scheme != 'https' or not parsed.hostname or parsed.username:
                raise AccessError('Browser Tool did not report an HTTPS login origin.', 403)
            origin = parsed.scheme + '://' + parsed.netloc
            if expected and origin != expected:
                raise AccessError('The provider-reported page does not match the saved login origin.', 403)
            return origin

    def fill(self, turn, meta, *, code=None, access=None):
        self.vault.assert_private(turn)
        with self.vault.lock_for(turn.home):
            self.login_origin(turn, meta.origin, otp=code is not None)
            access = access or self.vault.delegations.resolve(turn, meta.id)
            self.bind_access(turn, access)
            if code is not None:
                if not isinstance(code, str) or not re.fullmatch(r'[A-Za-z0-9]{4,32}', code):
                    raise AccessError('The verification code format is not supported.')
                from agent.redact import register_vault_redaction_value
                register_vault_redaction_value(code)
                _, state = self.state(turn)
                name, _ = self.selected(turn, state)
                return self.start(turn,
                    'On the current verification page at ' + meta.origin + ', enter verification_code '
                    'only in the visible one-time verification-code field. If there is no such field, stop and report that. '
                    'Stop before submitting. Do not read, display, return or copy the code; stay on this origin.',
                    name, credentials=code, origin=meta.origin, secret_alias='verification_code')
            if meta.login_method=='sms':
                from agent.redact import register_vault_redaction_value
                number=access.secret()['phone_number']
                register_vault_redaction_value(number)
                _, state=self.state(turn)
                name, _=self.selected(turn,state)
                return self.start(turn,
                    'On the current phone login page at '+meta.origin+', enter phone_number only in the visible phone-number login field. '
                    'Use national digits only when the field has a separate visible calling code matching the saved number prefix; otherwise preserve the full number. Never guess or truncate digits to fit. '
                    'If the page has only a verification-code field, stop. Stop before submitting. '
                    'Do not read, display, return or copy the number; stay on this exact origin.',
                    name,credentials=number,origin=meta.origin,secret_alias='phone_number')
            from agent.vault_store import VaultStore
            password = access.secret()['password']
            from agent.redact import register_vault_redaction_value
            register_vault_redaction_value(password)
            _, state = self.state(turn)
            name, _ = self.selected(turn, state)
            return self.start(turn,
                'On ' + meta.origin + ', the saved account identifier is ' + json.dumps(meta.identifier) + '. '
                'If the page displays a different account identifier, stop. '
                'Fill a visible username/email field with that identifier only if needed. '
                'Enter the supplied ' + urlsplit(meta.origin).hostname + ' secret only into the password field; '
                'it contains the password alone. If there is no password field, stop and report that. '
                'Stop before submitting. Do not display, return or copy credentials. Remain on this exact origin.',
                name, credentials=password, origin=meta.origin)

    def stop(self, turn, session=None, *, purge=False):
        with self.vault.lock_for(turn.home):
            path, state = self.state(turn)
            if purge:
                names = list(state['sessions'])
            elif not session and not turn.source.thread_id:
                names = list({name for thread, name in state['threads'].items()
                              if thread.startswith(turn.source.chat_id + ':')})
            else:
                names = [session or state['threads'].get(self.thread(turn))]
            pending = False
            for name in names:
                if name not in state['sessions']:
                    continue
                entry = state['sessions'][name]
                try:
                    if entry.get('dispatch_unknown'):
                        raise AccessError('An unacknowledged task must be reconciled before browser access can be cleared.', 409)
                    if entry.get('task_id'):
                        self.execute('STOP_TASK', {'taskId': entry['task_id']})
                    if purge or entry.get('cleanup_pending'):
                        raise AccessError('This provider cannot verify browser cookie deletion.', 409)
                except Exception:
                    pending = True
                    entry['cleanup_pending'] = True
                    self.save(path, state)
                    continue
                state['sessions'].pop(name)
                state['threads'] = {thread: value for thread, value in state['threads'].items() if value != name}
                self.save(path, state)
            if pending:
                raise AccessError('Browser cleanup is still pending. All known tasks were considered; this context remains blocked pending operator cleanup.', 409)

