def install_context(home, fleet, *, verify=True):
    home = Path(home).resolve(strict=True)
    fleet = Path(fleet).resolve(strict=True)
    settings = json.loads((fleet / 'fleet.json').read_text())
    atomic_json(home / '.clanker-execution' / 'context.json',
                {'home': str(home), 'fleet': str(fleet), 'enabled': True})
    for relative, kind in [('bin/browser-use', 'browser-use'), ('node/bin/agent-browser', 'agent-browser')]:
        launcher = (f"#!{settings['python_executable']}\nimport os, sys\n"
                    f"os.execv({settings['python_executable']!r}, [{settings['python_executable']!r}, "
                    f"{str(HERE / 'launcher.py')!r}, {kind!r}, *sys.argv[1:]])\n")
        write(home / relative, launcher, 0o700)
    plugin = home / 'plugins' / 'clanker-seatbelt'
    write(plugin / 'plugin.yaml', (HERE / 'plugin.yaml').read_text())
    write(plugin / '__init__.py', f"import sys\nsys.path.insert(0, {str(HERE.parent)!r})\nfrom seatbelt.plugin import register\n")
    context = Context(home)
    if verify:
        context.verify()
    return context


def activate_context(home, fleet):
    """Provision the sandboxed browser and trusted private-access tools."""
    context = install_context(home, fleet)
    if not context.settings.get('activated'):
        raise RuntimeError('The operator has not accepted browser execution')
    path = context.home / 'config.yaml'
    before = path.read_text()
    config = yaml.safe_load(before) or {}
    config.setdefault('platform_toolsets', {})['slack'] = ['clanker_browser']
    config['terminal'] = {'backend':'clanker_seatbelt', 'cwd':str(context.home/'workspace'),
                          'auto_source_bashrc':False, 'shell_init_files':[]}
    config.setdefault('tools', {})['tool_search'] = {'enabled':'off'}
    config.setdefault('security', {})['allow_lazy_installs'] = False
    # Never auto-discover the operator's password managers in member contexts.
    config['vault'] = {'onepassword':{'enabled':False},'bitwarden':{'enabled':False}}
    config.setdefault('plugins', {})['enabled'] = ['clanker-seatbelt']
    cloud_path = Path(context.settings['transport_home']) / '.clanker-cloud/config.json'
    cloud = json.loads(cloud_path.read_text()) if cloud_path.exists() else {}
    kernel = cloud.get('enabled') is True and cloud.get('provider') == 'kernel'
    if kernel:
        # The protected adapter loads the pinned provider itself; no raw global-env
        # Kernel plugin is enabled in the multiplexed requester profiles.
        config['plugins'].setdefault('entries', {}).setdefault('clanker-seatbelt', {})['allow_tool_override'] = True
        config['browser'] = {'cloud_provider':'kernel', 'backend':'agent-browser',
            'use_real_profile':False, 'headed':False, 'auto_local_for_private_urls':False,
            'allow_private_urls':False, 'allow_local_fallback':False, 'record_sessions':False,
            'extension_control':{'enabled':False}, 'inactivity_timeout':600}
    else:
        config['browser'] = {'cloud_provider':'local', 'backend':'browser-use', 'use_real_profile':False, 'headed':False,
                             'persistent_local_sessions':True}
    after = yaml.safe_dump(config, sort_keys=False)
    if before != after:
def get_browser_backend() -> str:
    """Configured browser backend key ("" = unset → default). YAML 1.1 parses an
    unquoted ``off`` as False — that must mean BACKEND_DISABLED, not "unset"."""
    raw = _read_browser_cfg().get("backend")
    return (BACKEND_DISABLED if raw is False else "") if isinstance(raw, bool) else str(raw or "").strip().lower()


def is_legacy_browser_use_cloud_config(browser_cfg: dict) -> bool:
    """True for pre-CLI direct-API Browser Use cloud configs. An explicit backend or
    a non-Browser-Use cloud_provider wins; Camofox is selected via env var, not
    cloud_provider, so a Camofox user with a stray BROWSER_USE_API_KEY keeps it."""
    if not isinstance(browser_cfg, dict) or browser_cfg.get("backend"):
        return False
    provider = str(browser_cfg.get("cloud_provider") or "").strip().lower()
    if provider not in {"browser-use", ""} or _use_gateway(browser_cfg) or _camofox_active(" during migration"):
        return False
    # Profile credential: a multiplexed secondary must not inherit the default's cloud mode.
    from agent.secret_scope import get_secret
    return bool(get_secret("BROWSER_USE_API_KEY", ""))


def is_browser_use_cli_mode() -> bool:
    """True when the Browser Use CLI replaces the built-in browser stack. Browser Use mode is the DEFAULT:
    unset ``browser.backend`` ("") enables it whenever the CLI is runnable (installed binary or uvx);
    ``browser.backend: off`` keeps the built-in browser_* tools. Camofox always falls back to the built-in
    tools (Firefox, custom HTTP API, no CDP surface for the harness)."""
    if _camofox_active():
        return False
    backend = get_browser_backend()
    return backend == _BACKEND_KEY if backend else (is_legacy_browser_use_cloud_config(_read_browser_cfg()) or _find_cli() is not None)

