    f.k.ensure_vault('TT','UA'); f.k.ensure_vault('TT','UB')
    dedicated=f.remote.create_vault('dedicated-fixture-account')
    handle='dedicated-account'
    f.k.metadata.bind_credential_vault('TT','UA',owner.home,handle,dedicated['id'])
    item=f.remote.create_credential(dedicated['id'],'login',[
        {'name':'phone_number','type':'text','required':True,'sensitive':False}])
    item=f.remote.ready(dedicated['id'],'login')
    f.k.metadata.put_item('TT','UA',owner.home,handle,'login',item['id'],'login',
        'Invited example','https://example.com',login_method='sms',fields=['phone_number'],
        status='ready',version=item['version'],vault_id=dedicated['id'])
    grant=f.service.delegations.invite({'team':'TT','owner':'UA'},handle,'UB')
