@pytest.mark.asyncio
async def test_pending_login_dedup_across_events_and_public_result_has_no_capabilities(kernel):
    f=kernel; first=f.turn(event='1'); second=f.turn(event='2')
    a=await f.k.request_access(first); b=await f.k.request_access(second)
    assert a['request_id']==b['request_id']
    assert len(f.remote.creates)==1
    assert 'https://' not in json.dumps(a) and 'private-fixture-capability' not in json.dumps(a)
    assert not list(f.service.policy.home.rglob('vault.json.enc'))


@pytest.mark.asyncio
async def test_pending_sms_login_is_not_reused_for_a_password_login(kernel):
    f=kernel; sms=f.turn(event='1')
    first=await f.k.request_access(sms,login_method='sms')
    password=f.turn(event='2')
    f.controls[f.task_id(password)]=[{'index':0,'type':'password','autocomplete':'current-password',
            'label':'Password','name':'password','maxLength':128,'formIndex':0}]
    second=await f.k.request_access(password,login_method='password')
    assert first['request_id'] != second['request_id']
    assert len(f.remote.creates)==2


@pytest.mark.asyncio
async def test_remote_ready_version_becomes_durable_owner_resume(kernel):
    f=kernel; turn=f.turn(); waiting=await f.k.request_access(turn)
    collection=f.k.metadata.collection(waiting['request_id'],team='TT',owner='UA',home=turn.home)
    f.remote.ready(collection['vault_id'],collection['key'],version=7)
    f.k.poll()
    row=next(row for row in f.service.store.pending_resumes() if row['id']==waiting['request_id'])
    updated=f.k.metadata.collection(row['id'],team='TT',owner='UA',home=turn.home)
    assert updated['state']=='ready' and updated['version']=='7'
    assert f.k.record('TT','UA',row['handle'])['version']=='7'
    events=[]
    async def receive(event):
        events.append(event); event._gateway_accepted=True
        key=f.service.policy.adapter._event_session_key(event)
        f.service.policy.adapter._session_tasks[key]=asyncio.create_task(asyncio.sleep(0))
    f.service.policy.adapter.handle_message=receive
    await f.service.resume(row)
    assert len(events)==1 and events[0].source.user_id=='UA' and events[0].source.chat_id=='DUA'

